// ─────────────────────────────────────────────────────────────
// THE CAMPAIGN BRIEF - the only node you normally edit.
//
// One entry per client. Each client has its own Pinterest account
// (account_id) and its own board (board_id). Add as many pins per
// client as you like; they get spaced out automatically.
//
// Running this off a spreadsheet instead? Delete this node and connect
// Google Sheets / Airtable / an n8n Data Table. Just make sure each
// item comes out with these fields:
//   client, account_id, board_id, title, description, link, image
// ─────────────────────────────────────────────────────────────

const CAMPAIGN = [
  {
    client:     'Acme Home Goods',
    account_id: 'PASTE_CLIENT_ACCOUNT_ID',
    board_id:   'PASTE_CLIENT_BOARD_ID',
    pins: [
      {
        title:       'Small kitchen, big storage',
        description: '7 ways to claw back counter space without a remodel.\n\n#smallkitchen #storage #homeorganization',
        link:        'https://acme.example.com/blog/small-kitchen-storage',
        image:       'https://acme.example.com/img/kitchen-storage.jpg'
      },
      {
        title:       'The 20-minute pantry reset',
        description: 'A repeatable system for a pantry that stays tidy.\n\n#pantry #organization #homehacks',
        link:        'https://acme.example.com/blog/pantry-reset',
        image:       'https://acme.example.com/img/pantry-reset.jpg'
      }
    ]
  },
  {
    client:     'Bluebird Studio',
    account_id: 'PASTE_CLIENT_ACCOUNT_ID',
    board_id:   'PASTE_CLIENT_BOARD_ID',
    pins: [
      {
        title:       'Colour palettes that actually print well',
        description: 'Screen-perfect is not press-perfect. Here is what survives.\n\n#design #printdesign #colorpalette',
        link:        'https://bluebird.example.com/journal/print-palettes',
        image:       'https://bluebird.example.com/img/print-palettes.jpg'
      }
    ]
  }
];

// ─────────────────────────────────────────────────────────────

const cfg = $('Configure campaign timing').first().json;
const firstSlotHours = Number(cfg.first_slot_hours || 24);
const gapHours       = Number(cfg.gap_hours || 6);
const jitterMinutes  = Number(cfg.jitter_minutes || 20);

const out = [];

for (const c of CAMPAIGN) {
  (c.pins || []).forEach((p, i) => {
    const base   = Date.now() + firstSlotHours * 3600000 + i * gapHours * 3600000;
    const jitter = (Math.random() - 0.5) * 2 * jitterMinutes * 60000;

    out.push({
      json: {
        client:      c.client,
        pinterest_account_id: c.account_id,
        pinterest_board_id:   c.board_id,
        title:       p.title,
        description: p.description,
        link_url:    p.link,
        image_url:   p.image,
        slot:        i + 1,
        run_at:      new Date(base + jitter).toISOString()
      }
    });
  });
}

if (!out.length) {
  throw new Error('The campaign brief is empty - add at least one client with one pin.');
}

return out;

// The image was downloaded and uploaded one-for-one, so item {i} here is
// still item {i} of "Skip clients that are not configured". Merging by index rather than
// relying on paired-item lookups keeps this working after the Filter above
// has dropped rows.
const rows = $('Skip clients that are not configured').all();

return items.map((item, i) => ({
  json: { ...rows[i].json, asset_id: item.json.id },
  pairedItem: { item: i }
}));

// One row per client, ready to paste into a status update.
// Read from the node directly above the scheduler, not from the brief: the
// Filter may have dropped rows, so brief indexes no longer line up here.
const brief = $('Attach the uploaded asset ID').all();
const byClient = {};

items.forEach((item, i) => {
  const row = brief[i] ? brief[i].json : {};
  const key = row.client || 'unknown client';

  byClient[key] = byClient[key] || {
    client: key, scheduled: 0, first_run_at: null, last_run_at: null, pins: []
  };
  byClient[key].scheduled += 1;
  byClient[key].pins.push({
    title:       row.title,
    run_at:      row.run_at,
    link:        row.link_url,
    schedule_id: item.json.id || null
  });
});

return Object.values(byClient).map(c => {
  const times = c.pins.map(p => p.run_at).filter(Boolean).sort();
  c.first_run_at = times[0] || null;
  c.last_run_at  = times[times.length - 1] || null;
  return { json: c };
});
